sys_variable_value.value:
(function execute(inputs, outputs) {
    var fieldName = inputs.field_name; // e.g., "u_invoice_status"
    var newValue = inputs.new_value;   // The value you want to save
    var recordGr = inputs.record;      // The record pill from your lookup

    if (recordGr && fieldName) {
        // This is the magic: using bracket notation to set a dynamic field
        recordGr.setValue(fieldName, newValue);
        recordGr.update();
        
        outputs.status = "Success";
    } else {
        outputs.status = "Error: Missing record or field name";
    }
})(inputs, outputs);

